def norm_shape(cells):
    """A set of (r,c) cells translated so its bounding box starts at (0,0)."""
    mr = min(r for r, c in cells); mc = min(c for r, c in cells)
    return frozenset((r - mr, c - mc) for r, c in cells)

def occurrences(pattern, mask, height, width):
    """Every (i, j) where the shape fits entirely inside the cell mask."""
    mr = max(r for r, c in pattern); mc = max(c for r, c in pattern)
    return [(i, j) for i in range(height - mr) for j in range(width - mc)
            if all((i + r, j + c) in mask for r, c in pattern)]

def stamp_shape(grid, color, bg=0):
    """Copy the object of the given color onto every spot where its shape fits in the bg-colored cells."""
    cells = {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color}
    if not cells:
        return [row[:] for row in grid]
    shape = norm_shape(cells)
    mask = {(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == bg}
    out = [row[:] for row in grid]
    for i, j in occurrences(shape, mask, len(grid), len(grid[0])):
        for r, c in shape:
            out[i + r][j + c] = color
    return out
